export interface CheckoutSessionData {
  url: string;
  sessionId: string;
}

export class StripeService {
  private static readonly STRIPE_PUBLISHABLE_KEY = import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY;
  private static readonly API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000';

  static async createCheckoutSession(
    plan: 'standard' | 'premium',
    userId: string
  ): Promise<CheckoutSessionData> {
    try {
      // Vérifier que la clé publique Stripe est configurée
      if (!this.STRIPE_PUBLISHABLE_KEY) {
        throw new Error('Stripe publishable key is not configured. Please add VITE_STRIPE_PUBLISHABLE_KEY to your environment variables.');
      }

      const planPrices = {
        standard: {
          priceId: 'price_standard_monthly', // Remplacez par votre vrai Price ID Stripe
          amount: 10000, // 100€ en centimes
          name: 'Plan Standard'
        },
        premium: {
          priceId: 'price_premium_monthly', // Remplacez par votre vrai Price ID Stripe
          amount: 20000, // 200€ en centimes
          name: 'Plan Premium'
        }
      };

      const selectedPlan = planPrices[plan];

      // Pour le développement, on simule une session Stripe
      if (import.meta.env.DEV) {
        console.warn('Mode développement: Simulation de la session Stripe');
        
        // Simuler un délai réseau
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        // Retourner une URL de test
        return {
          url: `https://checkout.stripe.com/pay/test_session_${Date.now()}#`,
          sessionId: `cs_test_${Date.now()}`
        };
      }

      // En production, faire l'appel réel à votre backend
      const response = await fetch(`${this.API_BASE_URL}/api/create-checkout-session`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          priceId: selectedPlan.priceId,
          userId,
          plan,
          successUrl: `${window.location.origin}/dashboard?payment=success`,
          cancelUrl: `${window.location.origin}/dashboard?payment=cancelled`
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to create checkout session');
      }

      const data = await response.json();
      return data;

    } catch (error) {
      console.error('Erreur lors de la création de la session Stripe:', error);
      throw new Error('Impossible de créer la session de paiement');
    }
  }

  static async handleSuccessfulPayment(sessionId: string): Promise<boolean> {
    try {
      const response = await fetch(`${this.API_BASE_URL}/api/verify-payment`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ sessionId }),
      });

      if (!response.ok) {
        throw new Error('Failed to verify payment');
      }

      const data = await response.json();
      return data.success;

    } catch (error) {
      console.error('Erreur lors de la vérification du paiement:', error);
      return false;
    }
  }

  static getStripePublishableKey(): string {
    const key = this.STRIPE_PUBLISHABLE_KEY;
    if (!key) {
      throw new Error('Stripe publishable key is not configured');
    }
    return key;
  }
}